import java.util.*;
public class SinglyLinkedList { static class Node{int x;Node next;Node(int x){this.x=x;}} Node head; public void addFirst(int x){Node n=new Node(x);n.next=head;head=n;} public boolean contains(int x){for(Node n=head;n!=null;n=n.next)if(n.x==x)return true;return false;} public int removeFirst(){if(head==null)throw new NoSuchElementException("empty list");int x=head.x;head=head.next;return x;} public String toString(){StringBuilder s=new StringBuilder("[");for(Node n=head;n!=null;n=n.next){if(s.length()>1)s.append(", ");s.append(n.x);}return s.append("]").toString();} public static void run(){SinglyLinkedList l=new SinglyLinkedList();l.addFirst(3);l.addFirst(2);l.addFirst(1);System.out.println("Linked list: "+l+", contains 2="+l.contains(2)+", removeFirst="+l.removeFirst());System.out.println("Invariant: each node points to the next node; insert/remove at head O(1), search O(n).\n");} public static void main(String[] args){run();}}
